"""Source-scoped comparison enrichment, reviewed 2026-09-23.
NA reasons are explicit. An unextracted value is never called unreported.
"""
def enrich(P,E,D,meta):
    date='2026-09-23'; by={p['id']:p for p in P}
    fields=['Hardware','Batch size','Measurement scope']
    for p in P:
        for key in fields:p['details'].setdefault(key,'NA — not extracted')
        p.setdefault('fieldEvidence',{})
    def put(pid,values,url,loc,depth=True):
        p=by[pid]; eid=f'e{len(E)+1:04d}'
        E.append(dict(id=eid,paperId=pid,category='Paper claim',text='Comparison extraction: '+', '.join(values)+'. Values and measurement scope are recorded in the technical fields.',sourceUrl=url,sourceType='Original paper / official artifact',locator=loc,status='Verified',accessed=date))
        p['details'].update(values);p['evidenceIds'].append(eid)
        for key in values:p['fieldEvidence'][key]=eid
        if depth:p['reviewDepth']='Selected full-text sections'
        return eid
    def existing(pid,values):
        p=by[pid];p['details'].update(values)
        eid=next((e['id'] for e in E if e['paperId']==pid and e['category']=='Author-reported result'),p['evidenceIds'][1])
        for key in values:p['fieldEvidence'][key]=eid
    nr='NA — not reported in reviewed sections'
    et='https://arxiv.org/html/2202.06335v2'
    nm='https://arxiv.org/html/2405.11449v2'
    plus='https://arxiv.org/html/2601.21792v1'
    ya='https://ojs.aaai.org/index.php/AAAI/article/view/25674/25446'
    put('etbert',{'Pretraining datasets':'About 30 GB: public traffic and CSTNET captures (about 15 GB each).','Training / evaluation datasets':'Cross-Platform Android/iOS, ISCX-VPN service/app, ISCX-Tor, USTC-TFC and CSTNET-TLS1.3; separate tasks.','Hardware':'NVIDIA Tesla V100S (original experiments).','Batch size':'32 for pretraining and fine-tuning.','Measurement scope':'Original paper evaluates classification; later benchmark measurements use different implementations.','Throughput':nr,'Latency':nr,'Energy':nr,'Timing':'NA — no separate timing input described','Packet length':'NA — no separate length input described'},et,'Sections 3.3–4.3; experimental scope')
    put('yatc',{'Fine-tuning objective':'Cross-entropy; shared packet/flow encoder weights.','Hardware':'Four NVIDIA RTX3090 GPUs.','Batch size':'512 pretraining; 64 fine-tuning.','Reported results':'Original Table 2: USTC-TFC2016 accuracy/F1 97.86%; ISCXVPN accuracy 98.07%, F1 98.04%.','Throughput':nr,'Latency':nr,'FLOPs':nr,'Memory':nr,'Energy':nr,'Split strategy':'Separate dataset-specific training/testing; exact ratio NA — not extracted.','Measurement scope':'Original Sections 4.1–4.5 report classification, ablations and transfer; no numeric serving throughput extracted.','Timing':'NA — no separate timing input described','Packet length':'Fixed byte crop/padding; no separate length input described'},ya,'Sections 3.3, 4.1–4.5; Table 2')
    put('netmamba',{'Traffic unit definition':'Five-tuple flow; first five packets.','Packets / bytes':'5 × (80 header + 240 payload bytes); 1,600 bytes; stride length 4.','Header':'Yes; anonymised header fields.','Architecture':'4-block Mamba encoder (256 dimensions); 2-block decoder (128).','Parameters':'2.2M pretraining / 1.9M fine-tuning (Table IV).','Training / evaluation datasets':'Cross-Platform Android/iOS, CICIoT2022, ISCXTor2016, ISCXVPN2016, USTC-TFC2016.','Pretraining datasets':'Same six public collections; exact pretraining overlap must be checked in the released preparation.','Metrics':'Accuracy, precision, recall, weighted F1.','Hardware':'Xeon Gold 6240C; four A100 40 GB GPUs.','Batch size':'128 pretraining; 64 fine-tuning; inference batch sweep.','Throughput':'1.22–60.11× baseline speedup; absolute flows/s plotted by batch size in Fig. 3. ET-BERT comparator uses packets/s.','Memory':'GPU-memory/batch curves in Fig. 3; numeric point NA — not transcribed.','FLOPs':nr,'Latency':nr,'Energy':nr,'Measurement scope':'Offline model inference, not end-to-end packet arrival-to-decision throughput.','Timing':'NA — no separate timing channel','Direction':'Flow ordering; explicit direction channel NA — not extracted','Packet length':'Fixed byte cropping/padding, not a separate length sequence.'},nm,'Sections V–VII; Tables III–V; Fig. 3')
    # These are explicitly external measurements, not silently original-paper values.
    for pid,value in [('etbert','187.4M pretraining / 136.4M fine-tuning'),('yatc','2.3M pretraining / 2.1M fine-tuning'),('fsnet','5.3M fine-tuning')]:
        put(pid,{'Parameters':value+' — NetMamba authors’ baseline implementation, not a universal count.'},nm,'Table IV: third-party baseline implementation',False)
    e=put('netmambaplus',{'Input representation':'Raw bytes plus packet-size and inter-arrival sequences.','Architecture':'Mamba backbone; framework also studies a Flash-Attention Transformer.','Header':'Yes','Timing':'Inter-arrival sequence','Packet length':'Packet-size sequence','Parameters':'2.6M pretraining / 1.9M fine-tuning (Table IV).','Training / evaluation datasets':'CipherSpectrum, CSTNET-TLS1.3, CICIoT2022, ISCXVPN2016, USTC-TFC2016; Huawei-VPN also evaluated.','Split strategy':'Within-dataset training; an additional first-packet-time-ordered test probes temporal shift.','Metrics':'Accuracy, F1; OOD AUROC and FPR95.','Throughput':'261.87 Mb/s mean; 29.85–335.21 Mb/s range (online batch inference).','Latency':'3.15 s mean batch latency; range 0.02–5.68 s. Not per-packet latency.','Hardware':'Online: Xeon Platinum 8375C, A30 24 GB, ConnectX-5 NIC; 512 GB host RAM.','Batch size':'Online: dynamic; new flow batch every 3 s.','Memory':'24 GB GPU and 512 GB host are installed capacities, not measured peak usage.','Measurement scope':'Online system (§VIII-I); offline sample/s comparisons are a separate experiment.','Deployment limitations':'Windowing, queueing and traffic mix constrain interpretation. Temporal-shift accuracy drops are still reported.','Energy':nr},plus,'Table IV; Sections VIII-H–J')
    by['netmambaplus']['openWorld']='Yes (cross-dataset OOD detection)'
    by['netmambaplus']['crossDataset']='Partial'
    by['netmambaplus']['code']='https://github.com/wangtz19/NetMamba'
    by['netmambaplus']['reproducibility']='Artifact linked; not rerun'
    by['netmambaplus']['datasets']=list(dict.fromkeys(by['netmambaplus']['datasets']+['cipherspectrum','cstnet','ciciot2022','iscxvpn','ustc']))
    for key,note in [('Open-world recognition','CipherSpectrum is ID; other datasets supply OOD samples. Domain shift and unknown labels are entangled.'),('Unknown applications','OOD application task is studied; this is not class discovery in a shared deployment.'),('Temporal robustness','Time-ordered evaluation reports degradation; robustness is investigated, not solved.')]:
        by['netmambaplus']['gaps'][key]=dict(state='Addressed',note=note,evidence=[e])
    put('netfound',{'Header':'Protocol-aware header fields; payload and IP excluded in v5.','Timing':'Operational timing metadata','Direction':'Operational direction metadata','Architecture':'Hierarchical burst/flow attention with shared parameters.','Training / evaluation datasets':'Intrinsic: Crossmarket, CICIDS2017, CAIDA, MAWI. Downstream: USTC, ISCX-VPN, CICIDS2017, Crossmarket.','Fine-tuning objective':'Frozen-encoder and end-to-end downstream experiments.','Latency':'As low as 11 ms/flow reported in Appendix A; variant/batch conditions matter.','Throughput':'Preprocessing on 128 cores: filtering 2,000, splitting 216, field extraction 970 flows/s. These are NOT model-inference rates.','Memory':'Appendix A reports GPU-memory profiles; numeric variant-specific value NA — not extracted.','Measurement scope':'v5 only; preprocessing rates, model inference and training costs are different measurements.','Energy':'NA — GPU-hours are training cost, not energy in joules.','Hardware':'Pretraining: A100 40 GB GPUs, 128 initially then 80; preprocessing: 128 CPU cores.'},'https://arxiv.org/html/2310.17025v5','Sections 3–5; Appendix A')
    put('flowmae',{'Hardware':'Official environment: i7-12700K and two RTX3090Ti GPUs.','Measurement scope':'Offline samples/s; one sample follows the burst representation. Not packets/s.','Latency':'NA — no absolute latency in reviewed repository summary','Energy':'NA — not reported in reviewed repository summary'},'https://github.com/NLear/Flow-MAE','README Introduction and System Requirements',False)
    existing('refinery',{'Throughput':'10 Gbps traffic monitoring while producing representations.','Measurement scope':'Feature measurement / representation production, not a universal classifier rate.'})
    existing('cato',{'Throughput':'Up to 3.7× higher zero-loss throughput than feature-optimisation baselines.','Latency':'Up to 3,600× lower inference latency versus the paper’s baselines.','Measurement scope':'Relative pipeline optimisation results; no universal absolute rate implied.'})
    existing('akem',{'Hardware':'Intel Tofino programmable switch.','Latency':'Sub-microsecond decision delay in the reported testbed.','Measurement scope':'Switch decision delay; observation and upstream preprocessing are separate.','Memory':'Average hardware-resource use below 10%; not a RAM/VRAM measurement.'})
    put('serveflow',{'Throughput':'>48.5k new flows/s on a 16-core CPU server (v2 abstract).','Latency':'76.3% of flows below 16 ms end-to-end (v2 abstract).','Metrics':'Service rate, end-to-end latency, miss rate and F1.','Architecture':'Fast/slow cascade: decision trees, RF, LightGBM, XGBoost and CNN candidates.','Input representation':'Packet-depth-dependent features and confidence-based escalation.','Training / evaluation datasets':'Service recognition (23,487 flows), device identification (50,017 flows), video-call QoE (36,928 seconds).','Split strategy':'50/10/40 train/validation/test in v2.','Hardware':'AMD EPYC 7302P, 16 cores/32 threads, 64 GB RAM; PF_RING and ONNX Runtime.','Measurement scope':'Traffic replay with arrival timing preserved; flow-level and continuous QoE tasks differ.','Version notes':'Metadata is the 2024 work; detailed setup here uses arXiv v2 (24 October 2024).'},'https://arxiv.org/html/2402.03694v2','Abstract; Sections 4–5.1')
    # Preserve the earlier abstract's measurement and label its version/scope.
    put('bos',{'Architecture':'On-switch RNN plus off-switch inference fallback.','Throughput':'100 Gbps physical testbed; 1.6 Tbps scaling is simulation.','Hardware':'Wedge 100BF-32X switch; fallback server with Xeon Gold 6348 CPUs and A100 GPU.','Measurement scope':'Physical and simulated results are separate; some flows use fallback.','Training / evaluation datasets':'ISCXVPN2016, BoT-IoT, CICIoT2022 and PeerRush.','Metrics':'Macro-F1, throughput and fallback behaviour.','Deployment limitations':'Fallback capacity and flow concurrency affect end-to-end latency.'},'https://www.usenix.org/system/files/nsdi24-yan.pdf','Figures 11–12; Appendix A.3')
    put('leo',{'Architecture':'Decision-tree inference with stateful feature extraction in the data plane.','Hardware':'Intel Tofino programmable switches.','Throughput':'Multi-terabit line-rate classification claimed; exact tested rate NA — not extracted.','Measurement scope':'In-switch classifier; resource/model-capacity limits apply.','Latency':'Nominal latency overhead reported; numeric value NA — not extracted.'},'https://www.usenix.org/conference/nsdi24/presentation/jafri','Official abstract',False)
    put('nepco',{'Architecture':'Convolutional pretrained model with on-SmartNIC execution.','Hardware':'NVIDIA BlueField-3 SmartNIC.','Throughput':'Network load up to 19.81 Mpps / 165.14 Gbps; separately, 5,000 new flows/s in Table IV.','Latency':'2.23–2.47 ms analysis latency; at 5,000 new flows/s: mean 2.41 ms, p99 2.71 ms.','Measurement scope':'One-minute continuous tests. Later packets of analysed flows are filtered; Mpps is not fresh model inferences/s.','Metrics':'Macro-F1, throughput, mean and p99 latency.','Deployment limitations':'Traffic observation, flow-arrival rate and hardware execution all affect portability.'},'https://arxiv.org/html/2508.02001v2','Section V-C; Figures 7–9; Table IV')
    # Populate already-known fields without presenting metadata as new full-text review.
    for p in P:
        d=p['details']
        if p['pretraining']=='No':
            for key in ['Pretraining objective','Pretraining datasets']:
                if d[key]=='Needs verification':d[key]='NA — no pretraining stage recorded for this contribution'
        if d['Training / evaluation datasets']=='Needs verification' and p['datasets']:
            d['Training / evaluation datasets']='Recorded collection links: '+', '.join(next(x['name'] for x in D if x['id']==i) for i in p['datasets'])+'. Exact task subsets/roles: NA — not extracted.'
        if d['Architecture']=='Needs verification':d['Architecture']='Recorded method family: '+p['family']+'. Architecture details: NA — not extracted.'
        for key,value in d.items():
            if value=='Needs verification':d[key]='NA — not extracted'
        # A default scope is a curation statement, not a result attributed to the paper.
        if d['Measurement scope']=='NA — not extracted':d['Measurement scope']='Use only the setup stated in the cited results; unextracted conditions remain NA.'
    for d in D:d['papers']=[p['id'] for p in P if d['id'] in p['datasets']]
    meta['updated']=date
    meta['comparisonNotation']={'notReported':'NA — not reported in reviewed sections','notApplicable':'NA — no applicable stage','notExtracted':'NA — not extracted; source may contain the value'}
    meta['comparisonReviewPapers']=['etbert','yatc','netmamba','netmambaplus','netfound','flowmae','fsnet','refinery','cato','akem','serveflow','bos','leo','nepco']
